use anyhow::Result;
use std::fs;
use crate::config::Config;
use crate::cli::{AddTarget, ListTarget};

pub mod attractors;
pub mod iterations;
pub mod personas;
pub mod purposes;
pub mod research;
pub mod stressors;
pub mod terminology;

pub fn init(cfg: &Config) -> Result<()> {
    let dir = &cfg.residual_dir;
    fs::create_dir_all(dir.join("iterations"))?;
    fs::create_dir_all(dir.join("personas"))?;
    fs::create_dir_all(dir.join("research"))?;

    // Write empty config.toml if not present
    let config_path = dir.join("config.toml");
    if !config_path.exists() {
        fs::write(&config_path, "# residual configuration\n[validation]\nstrict = true\n\n[skills]\ntoken_warn = 1000\n")?;
    }

    // Write empty CSVs with headers if not present
    let csvs: &[(&str, &str)] = &[
        ("stressors.csv", "id,description,naive_change,traits,components_affected,attractor_id"),
        ("purposes.csv", "id,description,feature,traits,components_enabled,attractor_id"),
        ("attractors.csv", "id,name,valence,description,phase_state"),
        ("terminology.csv", "term,definition,domain,related_terms"),
    ];
    for (filename, header) in csvs {
        let path = dir.join(filename);
        if !path.exists() {
            fs::write(&path, format!("{}\n", header))?;
        }
    }

    println!("Initialized residual/ at {}", dir.display());
    Ok(())
}

pub fn add(cfg: &Config, target: AddTarget) -> Result<()> {
    let dir = &cfg.residual_dir;
    match target {
        AddTarget::Stressor { description, attractor_id, naive_change, traits, components } => {
            let existing = stressors::load(dir)?;
            let id = stressors::next_id(&existing);
            stressors::append(dir, stressors::Stressor {
                id: id.clone(),
                description,
                attractor_id,
                naive_change,
                traits,
                components_affected: components,
            })?;
            println!("Added stressor {}", id);
        }
        AddTarget::Purpose { description, attractor_id, feature, traits, components } => {
            let existing = purposes::load(dir)?;
            let id = purposes::next_id(&existing);
            purposes::append(dir, purposes::Purpose {
                id: id.clone(),
                description,
                attractor_id,
                feature,
                traits,
                components_enabled: components,
            })?;
            println!("Added purpose {}", id);
        }
        AddTarget::Attractor { name, valence, description, phase_state } => {
            let existing = attractors::load(dir)?;
            let id = attractors::next_id(&existing);
            let valence: attractors::Valence = valence.parse()?;
            attractors::append(dir, attractors::Attractor {
                id: id.clone(),
                name,
                valence,
                description,
                phase_state,
            })?;
            println!("Added attractor {}", id);
        }
        AddTarget::Term { term, definition, domain, related } => {
            terminology::append(dir, terminology::Term {
                term: term.clone(),
                definition,
                domain,
                related_terms: related,
            })?;
            println!("Added term '{}'", term);
        }
        AddTarget::Persona { name, role, concerns, desires } => {
            personas::create(dir, personas::Persona {
                name: name.clone(),
                role,
                concerns,
                desires,
                stressor_ids: vec![],
            })?;
            println!("Added persona '{}'", name);
        }
        AddTarget::Iteration { notes, ri_score } => {
            let n = iterations::next_n(dir)?;
            let date = chrono::Local::now().format("%Y-%m-%d").to_string();
            iterations::create(dir, iterations::IterationMeta {
                n,
                date,
                ri_score,
                n_val: String::new(),
                k_val: String::new(),
                p_val: String::new(),
                notes,
            })?;
            println!("Added iteration {}", n);
        }
    }
    Ok(())
}

pub fn list(cfg: &Config, target: ListTarget) -> Result<()> {
    let dir = &cfg.residual_dir;
    match target {
        ListTarget::Stressors => {
            let items = stressors::load(dir)?;
            if items.is_empty() {
                println!("No stressors.");
            } else {
                for s in &items {
                    println!("[{}] {} (attractor: {})", s.id, s.description, s.attractor_id);
                }
            }
        }
        ListTarget::Purposes => {
            let items = purposes::load(dir)?;
            if items.is_empty() {
                println!("No purposes.");
            } else {
                for p in &items {
                    println!("[{}] {} (feature: {})", p.id, p.description, p.feature);
                }
            }
        }
        ListTarget::Attractors => {
            let items = attractors::load(dir)?;
            if items.is_empty() {
                println!("No attractors.");
            } else {
                for a in &items {
                    println!("[{}] {} ({:?})", a.id, a.name, a.valence);
                }
            }
        }
        ListTarget::Terminology => {
            let items = terminology::load(dir)?;
            if items.is_empty() {
                println!("No terminology.");
            } else {
                for t in &items {
                    println!("{}: {}", t.term, t.definition);
                }
            }
        }
        ListTarget::Personas => {
            let names = personas::list_names(dir)?;
            if names.is_empty() {
                println!("No personas.");
            } else {
                for name in &names {
                    println!("{}", name);
                }
            }
        }
        ListTarget::Iterations => {
            let items = iterations::list(dir)?;
            if items.is_empty() {
                println!("No iterations.");
            } else {
                let mut sorted = items;
                sorted.sort_by_key(|i| i.n);
                for meta in &sorted {
                    println!("Iteration {}: {} (Ri: {})", meta.n, meta.date, meta.ri_score);
                }
            }
        }
    }
    Ok(())
}

use anyhow::Result;
use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "residual", about = "NKP Residuality architecture CLI", version)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

#[derive(Subcommand)]
pub enum Command {
    Init,
    Add {
        #[command(subcommand)]
        target: AddTarget,
    },
    List {
        #[command(subcommand)]
        target: ListTarget,
    },
    Verify {
        #[command(subcommand)]
        check: VerifyCheck,
    },
    Matrix {
        #[command(subcommand)]
        op: MatrixOp,
    },
    SkillShow {
        name: String,
        #[arg(long)]
        version: bool,
    },
    SkillInstall {
        name: String,
        #[arg(long, default_value = "agnostic")]
        agent: String,
        #[arg(long)]
        global: bool,
    },
    SkillData {
        name: String,
    },
    SkillList,
    SkillCheck {
        name: String,
        #[arg(long, default_value = "agnostic")]
        agent: String,
    },
    Tag {
        #[command(subcommand)]
        op: TagOp,
    },
    Generate {
        #[command(subcommand)]
        artifact: GenerateArtifact,
    },
    Config,
}

#[derive(Subcommand)]
pub enum AddTarget {
    Stressor {
        #[arg(long)] description: String,
        #[arg(long)] attractor_id: String,
        #[arg(long)] naive_change: String,
        #[arg(long, default_value = "")] traits: String,
        #[arg(long, default_value = "")] components: String,
    },
    Purpose {
        #[arg(long)] description: String,
        #[arg(long)] attractor_id: String,
        #[arg(long)] feature: String,
        #[arg(long, default_value = "")] traits: String,
        #[arg(long, default_value = "")] components: String,
    },
    Attractor {
        #[arg(long)] name: String,
        #[arg(long)] valence: String,
        #[arg(long)] description: String,
        #[arg(long, default_value = "")] phase_state: String,
    },
    Term {
        #[arg(long)] term: String,
        #[arg(long)] definition: String,
        #[arg(long, default_value = "")] domain: String,
        #[arg(long, default_value = "")] related: String,
    },
    Persona {
        #[arg(long)] name: String,
        #[arg(long)] role: String,
        #[arg(long, default_value = "")] concerns: String,
        #[arg(long, default_value = "")] desires: String,
    },
    Iteration {
        #[arg(long, default_value = "")] notes: String,
        #[arg(long, default_value = "")] ri_score: String,
    },
}

#[derive(Subcommand)]
pub enum ListTarget {
    Stressors,
    Purposes,
    Attractors,
    Terminology,
    Personas,
    Iterations,
}

#[derive(Subcommand)]
pub enum VerifyCheck {
    Traits,
    Links,
    All,
}

#[derive(Subcommand)]
pub enum MatrixOp {
    Show,
    Calc,
    Criticality,
    Ri {
        #[arg(long)] stressors: usize,
        #[arg(long)] naive_survived: usize,
        #[arg(long)] residual_survived: usize,
    },
    Fusion,
    Fission,
}

#[derive(Subcommand)]
pub enum TagOp {
    Scan {
        #[arg(default_value = ".")] path: String,
    },
    Report {
        #[arg(default_value = ".")] path: String,
    },
}

#[derive(Subcommand)]
pub enum GenerateArtifact {
    Completions,
    Man,
    Hook,
}

pub fn run() -> Result<()> {
    let cli = Cli::parse();
    let cfg = crate::config::load()?;

    match cli.command {
        Command::Init => crate::storage::init(&cfg),
        Command::Add { target } => crate::storage::add(&cfg, target),
        Command::List { target } => crate::storage::list(&cfg, target),
        Command::Verify { check } => crate::verify::run(&cfg, check),
        Command::Matrix { op } => crate::nkp::run(&cfg, op),
        Command::SkillShow { name, version } => crate::skills::show(&name, version),
        Command::SkillInstall { name, agent, global } => crate::skills::install(&name, &agent, global),
        Command::SkillData { name } => crate::skills::data(&cfg, &name),
        Command::SkillList => crate::skills::list_all(),
        Command::SkillCheck { name, agent } => crate::skills::check(&name, &agent),
        Command::Tag { op } => crate::tags::run(&cfg, op),
        Command::Generate { artifact } => match artifact {
            GenerateArtifact::Completions => crate::skills::generate_completions(),
            GenerateArtifact::Man => crate::skills::generate_man(),
            GenerateArtifact::Hook => crate::skills::install_hook(),
        },
        Command::Config => crate::config::print(&cfg),
    }
}

