5	pub fn run(cfg: &Config, check: VerifyCheck) -> Result<()> {
6	    match check {
7	        VerifyCheck::Traits => {
8	            let violations = check_traits(cfg)?;
9	            if violations.is_empty() {
10	                println!("OK: all traits reference at least one terminology term.");
11	            } else {
12	                for v in &violations {
13	                    println!("VIOLATION [{}] {}: {} — {}", v.source, v.id, v.trait_str, v.reason);
14	                }
15	                println!("{} trait violation(s) found.", violations.len());
16	            }
17	        }
18	        VerifyCheck::Links => {
19	            let violations = check_links(cfg)?;
20	            if violations.is_empty() {
21	                println!("OK: all attractor links are valid.");
22	            } else {
23	                for v in &violations {
24	                    println!("VIOLATION [{}] {}: missing attractor '{}'", v.source, v.id, v.missing_attractor_id);
25	                }
26	                println!("{} link violation(s) found.", violations.len());
27	            }
28	        }
29	        VerifyCheck::All => {
30	            let trait_violations = check_traits(cfg)?;
31	            let link_violations = check_links(cfg)?;
32	            let total = trait_violations.len() + link_violations.len();
33	            for v in &trait_violations {
34	                println!("TRAIT VIOLATION [{}] {}: {} — {}", v.source, v.id, v.trait_str, v.reason);
35	            }
36	            for v in &link_violations {
37	                println!("LINK VIOLATION [{}] {}: missing attractor '{}'", v.source, v.id, v.missing_attractor_id);
38	            }
39	            if total == 0 {
40	                println!("OK: all checks passed.");
41	            } else {
42	                println!("{} total violation(s) found.", total);
43	            }
44	        }
45	    }
46	    Ok(())
47	}
48	
49	pub fn check_traits(cfg: &Config) -> Result<Vec<TraitViolation>> {
50	    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
51	    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
52	    let terms = crate::storage::terminology::load(&cfg.residual_dir)?;
53	    let term_set = crate::storage::terminology::term_set(&terms);
54	
55	    let mut violations = Vec::new();
56	
57	    // Check stressor traits
58	    for stressor in &stressors {
59	        for raw_trait in stressor.traits.split('|') {
60	            let raw_trait = raw_trait.trim();
61	            if raw_trait.is_empty() {
62	                continue;
63	            }
64	            match parse_trait(raw_trait) {
65	                None => {
66	                    violations.push(TraitViolation {
67	                        source: "stressor".to_string(),
68	                        id: stressor.id.clone(),
69	                        trait_str: raw_trait.to_string(),
70	                        reason: "trait must have at least subject verb predicate (3 words)".to_string(),
71	                    });
72	                }
73	                Some(parts) => {
74	                    if !trait_uses_terminology(&parts, &term_set) {
75	                        violations.push(TraitViolation {
76	                            source: "stressor".to_string(),
77	                            id: stressor.id.clone(),
78	                            trait_str: raw_trait.to_string(),
79	                            reason: "no word in this trait matches the project terminology".to_string(),
80	                        });
81	                    }
82	                }
83	            }
84	        }
85	    }
86	
87	    // Check purpose traits
88	    for purpose in &purposes {
89	        for raw_trait in purpose.traits.split('|') {
90	            let raw_trait = raw_trait.trim();
91	            if raw_trait.is_empty() {
92	                continue;
93	            }
94	            match parse_trait(raw_trait) {
95	                None => {
96	                    violations.push(TraitViolation {
97	                        source: "purpose".to_string(),
98	                        id: purpose.id.clone(),
99	                        trait_str: raw_trait.to_string(),
100	                        reason: "trait must have at least subject verb predicate (3 words)".to_string(),
101	                    });
102	                }
103	                Some(parts) => {
104	                    if !trait_uses_terminology(&parts, &term_set) {
105	                        violations.push(TraitViolation {
106	                            source: "purpose".to_string(),
107	                            id: purpose.id.clone(),
108	                            trait_str: raw_trait.to_string(),
109	                            reason: "no word in this trait matches the project terminology".to_string(),
110	                        });
111	                    }
112	                }
113	            }
114	        }
115	    }
116	
117	    Ok(violations)
118	}
119	
120	pub fn check_links(cfg: &Config) -> Result<Vec<LinkViolation>> {
121	    let stressors = crate::storage::stressors::load(&cfg.residual_dir)?;
122	    let purposes = crate::storage::purposes::load(&cfg.residual_dir)?;
123	    let attractors = crate::storage::attractors::load(&cfg.residual_dir)?;
124	    let attractor_ids: std::collections::HashSet<String> =
125	        attractors.iter().map(|a| a.id.clone()).collect();
126	
127	    let mut violations = Vec::new();
128	
129	    for stressor in &stressors {
130	        if !stressor.attractor_id.is_empty() && !attractor_ids.contains(&stressor.attractor_id) {
131	            violations.push(LinkViolation {
132	                source: "stressor".to_string(),
133	                id: stressor.id.clone(),
134	                missing_attractor_id: stressor.attractor_id.clone(),
135	            });
136	        }
137	    }
138	
139	    for purpose in &purposes {
140	        if !purpose.attractor_id.is_empty() && !attractor_ids.contains(&purpose.attractor_id) {
141	            violations.push(LinkViolation {
142	                source: "purpose".to_string(),
143	                id: purpose.id.clone(),
144	                missing_attractor_id: purpose.attractor_id.clone(),
145	            });
146	        }
147	    }
148	
149	    Ok(violations)
150	}
151	
152	/// Parse a trait string into (subject, verb, predicates).
153	/// Format: "<subject> <verb> <pred1> [<pred2>...]"
154	/// Returns None if fewer than 3 words.
