        let violations = check_traits(&cfg).unwrap();
        assert!(violations.is_empty(), "expected no violations for valid trait");
    }

    #[test]
    fn check_traits_no_matching_term_is_violation() {
        let dir = tempdir().unwrap();
        let cfg = cfg_for(dir.path());
        terminology::append(
            dir.path(),
            terminology::Term {
                term: "auth".to_string(),
