#[test]
fn skill_data_naive_draft_excludes_stressors_section() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let out = run(&dir, &["skill-data", "naive-draft"]);
    let stdout = String::from_utf8_lossy(&out.stdout);
